package cn.zhuatech.siem.deep;import cn.zhuatech.siem.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/admin/siem-ops") public class DeepAdminController{private final DeepDomainService s;public DeepAdminController(DeepDomainService s){this.s=s;}@PostMapping("/sources/{id}/activate")ApiResponse<?> activate(@PathVariable Long id){return ApiResponse.ok(s.activate(id));}@PostMapping("/rules")ApiResponse<?> rule(@Valid @RequestBody DeepDomainService.RuleRequest r){return ApiResponse.ok(s.rule(r));}@PostMapping("/incidents/{id}/close")ApiResponse<?> close(@PathVariable Long id,@Valid @RequestBody DeepDomainService.CloseRequest r){return ApiResponse.ok(s.close(id,r));}}
